import{_ as e,o as r,c as i,a2 as t}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_27_irl_gail_overview.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_27_irl_loop.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_27_occupancy_matching.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_27_gail_adversarial.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_27_driving_irl_boundary.png",g=JSON.parse('{"title":"专家到底在追求什么？从逆强化学习到 GAIL","description":"行为克隆把专家动作当作标签，DAgger 让专家为学习策略访问的状态重新打标签，但二者都没有回答一个更深的问题：专家为什么这样行动？在很多任务里，我们能观察到驾驶轨迹，却很难写出“安全、效率、舒适、礼让”之间的精确奖励。Inverse Reinforcement Learning（逆强化学习，IRL","frontmatter":{"title":"专家到底在追求什么？从逆强化学习到 GAIL","description":"行为克隆把专家动作当作标签，DAgger 让专家为学习策略访问的状态重新打标签，但二者都没有回答一个更深的问题：专家为什么这样行动？在很多任务里，我们能观察到驾驶轨迹，却很难写出“安全、效率、舒适、礼让”之间的精确奖励。Inverse Reinforcement Learning（逆强化学习，IRL","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":8,"source":"2026-08-13/rl_series_27_irl_gail.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_27_irl_gail_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-27-irl-gail"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"专家到底在追求什么？从逆强化学习到 GAIL"}],["meta",{"property":"og:description","content":"行为克隆把专家动作当作标签，DAgger 让专家为学习策略访问的状态重新打标签，但二者都没有回答一个更深的问题：专家为什么这样行动？在很多任务里，我们能观察到驾驶轨迹，却很难写出“安全、效率、舒适、礼让”之间的精确奖励。Inverse Reinforcement Learning（逆强化学习，IRL"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-27-irl-gail"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_27_irl_gail_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"专家到底在追求什么？从逆强化学习到 GAIL"}],["meta",{"name":"twitter:description","content":"行为克隆把专家动作当作标签，DAgger 让专家为学习策略访问的状态重新打标签，但二者都没有回答一个更深的问题：专家为什么这样行动？在很多任务里，我们能观察到驾驶轨迹，却很难写出“安全、效率、舒适、礼让”之间的精确奖励。Inverse Reinforcement Learning（逆强化学习，IRL"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_27_irl_gail_overview.png"}]],"prev":{"text":"专家只看训练集不够：DAgger 如何修复行为克隆的分布偏移","link":"/rl/rl-series-26-dagger-dataset-aggregation"},"next":{"text":"AlphaStar 拆解篇一：复杂游戏如何表示状态与组合动作","link":"/rl/rl-series-28-alphastar-representation-actions"}},"headers":[],"relativePath":"rl/rl-series-27-irl-gail.md","filePath":"rl/rl-series-27-irl-gail.md","lastUpdated":null}'),d={name:"rl/rl-series-27-irl-gail.md"};function c(p,a,_,u,b,m){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="专家到底在追求什么-从逆强化学习到-gail" tabindex="-1">专家到底在追求什么？从逆强化学习到 GAIL <a class="header-anchor" href="#专家到底在追求什么-从逆强化学习到-gail" aria-label="Permalink to &quot;专家到底在追求什么？从逆强化学习到 GAIL&quot;">​</a></h1><p>行为克隆把专家动作当作标签，DAgger 让专家为学习策略访问的状态重新打标签，但二者都没有回答一个更深的问题：专家为什么这样行动？在很多任务里，我们能观察到驾驶轨迹，却很难写出“安全、效率、舒适、礼让”之间的精确奖励。Inverse Reinforcement Learning（逆强化学习，IRL）尝试从专家轨迹反推出一个能解释行为的奖励或代价函数。</p><p>IRL 不是从示范唯一恢复真实人类价值。不同奖励可能诱导相同策略，奖励存在等价变换和不可辨识性。GAIL（Generative Adversarial Imitation Learning，生成对抗模仿学习）进一步跳过显式恢复奖励的中间结果，直接让策略产生的状态—动作分布接近专家分布。它适合复杂连续控制，却继承了对抗训练不稳定、分布覆盖和安全偏差问题。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-irl-反推的是解释行为的奖励" tabindex="-1">1.1 IRL 反推的是解释行为的奖励 <a class="header-anchor" href="#_1-1-irl-反推的是解释行为的奖励" aria-label="Permalink to &quot;1.1 IRL 反推的是解释行为的奖励&quot;">​</a></h3><p>给定环境、专家轨迹和奖励模型假设，IRL 寻找一个奖励，使专家行为比候选策略更合理。</p><h3 id="_1-2-奖励通常不唯一" tabindex="-1">1.2 奖励通常不唯一 <a class="header-anchor" href="#_1-2-奖励通常不唯一" aria-label="Permalink to &quot;1.2 奖励通常不唯一&quot;">​</a></h3><p>策略不变变换、特征相关性和有限示范都会导致多个奖励解释同一行为。不能把学到的奖励称为“人类真实价值”。</p><h3 id="_1-3-gail-直接匹配占用分布" tabindex="-1">1.3 GAIL 直接匹配占用分布 <a class="header-anchor" href="#_1-3-gail-直接匹配占用分布" aria-label="Permalink to &quot;1.3 GAIL 直接匹配占用分布&quot;">​</a></h3><p>判别器区分专家与策略状态—动作，策略通过强化学习让判别器难以区分。它更接近行为分布匹配，而不是显式奖励恢复。</p><h3 id="_1-4-示范安全性决定上限" tabindex="-1">1.4 示范安全性决定上限 <a class="header-anchor" href="#_1-4-示范安全性决定上限" aria-label="Permalink to &quot;1.4 示范安全性决定上限&quot;">​</a></h3><p>专家违规、偏置、场景覆盖不足会被 IRL 或 GAIL 学习。模仿“像专家”不等于超过专家，也不等于满足独立安全约束。</p><p><img src="'+l+'" alt="IRL 反推奖励与 GAIL 分布匹配的关系"></p><h2 id="二、为什么行为克隆之后还需要-irl" tabindex="-1">二、为什么行为克隆之后还需要 IRL <a class="header-anchor" href="#二、为什么行为克隆之后还需要-irl" aria-label="Permalink to &quot;二、为什么行为克隆之后还需要 IRL&quot;">​</a></h2><h3 id="_2-1-动作标签不能表达长期原因" tabindex="-1">2.1 动作标签不能表达长期原因 <a class="header-anchor" href="#_2-1-动作标签不能表达长期原因" aria-label="Permalink to &quot;2.1 动作标签不能表达长期原因&quot;">​</a></h3><p>同一个转角可能是为了避障、保持舒适或准备变道。单步动作标签不包含这些意图。</p><h3 id="_2-2-专家示范通常数量有限" tabindex="-1">2.2 专家示范通常数量有限 <a class="header-anchor" href="#_2-2-专家示范通常数量有限" aria-label="Permalink to &quot;2.2 专家示范通常数量有限&quot;">​</a></h3><p>如果奖励能解释轨迹，策略可以在环境中继续优化，而不是只复制有限状态。</p><h3 id="_2-3-奖励模型可以支持新场景" tabindex="-1">2.3 奖励模型可以支持新场景 <a class="header-anchor" href="#_2-3-奖励模型可以支持新场景" aria-label="Permalink to &quot;2.3 奖励模型可以支持新场景&quot;">​</a></h3><p>理论上，学到的目标函数能在不同初始状态和路线中指导策略。但这种泛化依赖奖励特征和环境模型假设。</p><h3 id="_2-4-irl-也可能放大示范偏差" tabindex="-1">2.4 IRL 也可能放大示范偏差 <a class="header-anchor" href="#_2-4-irl-也可能放大示范偏差" aria-label="Permalink to &quot;2.4 IRL 也可能放大示范偏差&quot;">​</a></h3><p>如果专家总是压线或偏好激进超车，IRL 可能把这些偶然行为解释成高价值目标。</p><h2 id="三、irl-的逆向推理是什么" tabindex="-1">三、IRL 的逆向推理是什么 <a class="header-anchor" href="#三、irl-的逆向推理是什么" aria-label="Permalink to &quot;三、IRL 的逆向推理是什么&quot;">​</a></h2><h3 id="_3-1-普通-rl-是奖励到策略" tabindex="-1">3.1 普通 RL 是奖励到策略 <a class="header-anchor" href="#_3-1-普通-rl-是奖励到策略" aria-label="Permalink to &quot;3.1 普通 RL 是奖励到策略&quot;">​</a></h3><p>强化学习给定环境和奖励 (r)，寻找最大化期望回报的策略 (\\pi)。</p><h3 id="_3-2-irl-是轨迹到奖励" tabindex="-1">3.2 IRL 是轨迹到奖励 <a class="header-anchor" href="#_3-2-irl-是轨迹到奖励" aria-label="Permalink to &quot;3.2 IRL 是轨迹到奖励&quot;">​</a></h3><p>IRL 给定专家轨迹 (\\tau_E)，寻找奖励 (r_\\psi)，使专家策略在该奖励下表现优良。</p><h3 id="_3-3-还需要环境转移或交互能力" tabindex="-1">3.3 还需要环境转移或交互能力 <a class="header-anchor" href="#_3-3-还需要环境转移或交互能力" aria-label="Permalink to &quot;3.3 还需要环境转移或交互能力&quot;">​</a></h3><p>若只看离线轨迹，奖励解释容易欠约束；很多 IRL 方法需要候选策略与环境交互，比较专家和当前策略的占用。</p><h3 id="_3-4-需要对奖励函数加限制" tabindex="-1">3.4 需要对奖励函数加限制 <a class="header-anchor" href="#_3-4-需要对奖励函数加限制" aria-label="Permalink to &quot;3.4 需要对奖励函数加限制&quot;">​</a></h3><p>线性特征奖励、正则化、最大熵或先验约束都用于减少不可辨识性。限制越强，稳定性可能越好，表达能力也可能越弱。</p><p><img src="'+o+'" alt="IRL 的专家轨迹、奖励学习与策略优化闭环"></p><h2 id="四、奖励不可辨识性从哪里来" tabindex="-1">四、奖励不可辨识性从哪里来 <a class="header-anchor" href="#四、奖励不可辨识性从哪里来" aria-label="Permalink to &quot;四、奖励不可辨识性从哪里来&quot;">​</a></h2><h3 id="_4-1-同一策略可以由不同奖励诱导" tabindex="-1">4.1 同一策略可以由不同奖励诱导 <a class="header-anchor" href="#_4-1-同一策略可以由不同奖励诱导" aria-label="Permalink to &quot;4.1 同一策略可以由不同奖励诱导&quot;">​</a></h3><p>多个奖励在访问到的状态区域上给出相同动作排序，策略无法仅凭示范区分它们。</p><h3 id="_4-2-未访问状态没有直接约束" tabindex="-1">4.2 未访问状态没有直接约束 <a class="header-anchor" href="#_4-2-未访问状态没有直接约束" aria-label="Permalink to &quot;4.2 未访问状态没有直接约束&quot;">​</a></h3><p>专家没走过的危险或长尾状态，奖励模型可以任意外推。策略一旦进入这些区域，行为可能完全不可预测。</p><h3 id="_4-3-特征设计决定可表达价值" tabindex="-1">4.3 特征设计决定可表达价值 <a class="header-anchor" href="#_4-3-特征设计决定可表达价值" aria-label="Permalink to &quot;4.3 特征设计决定可表达价值&quot;">​</a></h3><p>若奖励只看距离和速度，就无法表达让行、视线、道路规则等因素；加入相关特征又可能引入共线和偏置。</p><h3 id="_4-4-正则化不是事实证明" tabindex="-1">4.4 正则化不是事实证明 <a class="header-anchor" href="#_4-4-正则化不是事实证明" aria-label="Permalink to &quot;4.4 正则化不是事实证明&quot;">​</a></h3><p>平滑、稀疏和最大熵先验能选择某个解，但不能证明它就是专家真实意图。</p><h2 id="五、gail-怎样把-irl-变成对抗学习" tabindex="-1">五、GAIL 怎样把 IRL 变成对抗学习 <a class="header-anchor" href="#五、gail-怎样把-irl-变成对抗学习" aria-label="Permalink to &quot;五、GAIL 怎样把 IRL 变成对抗学习&quot;">​</a></h2><h3 id="_5-1-判别器区分专家与策略数据" tabindex="-1">5.1 判别器区分专家与策略数据 <a class="header-anchor" href="#_5-1-判别器区分专家与策略数据" aria-label="Permalink to &quot;5.1 判别器区分专家与策略数据&quot;">​</a></h3><p>判别器 (D_\\omega(s,a)) 接收状态—动作对，输出其来自专家还是当前策略的概率。</p><h3 id="_5-2-策略试图骗过判别器" tabindex="-1">5.2 策略试图骗过判别器 <a class="header-anchor" href="#_5-2-策略试图骗过判别器" aria-label="Permalink to &quot;5.2 策略试图骗过判别器&quot;">​</a></h3><p>策略与环境交互产生新轨迹，使用判别器信号构造代价或奖励，再用策略梯度更新。</p><h3 id="_5-3-目标是匹配占用测度" tabindex="-1">5.3 目标是匹配占用测度 <a class="header-anchor" href="#_5-3-目标是匹配占用测度" aria-label="Permalink to &quot;5.3 目标是匹配占用测度&quot;">​</a></h3><p>策略不必逐帧复制专家，只要在相关状态—动作分布上足够接近，就能降低判别器区分能力。</p><p><img src="'+h+'" alt="专家与策略的状态—动作占用分布需要在关键区域匹配"></p><h3 id="_5-4-对抗训练同时包含两个优化问题" tabindex="-1">5.4 对抗训练同时包含两个优化问题 <a class="header-anchor" href="#_5-4-对抗训练同时包含两个优化问题" aria-label="Permalink to &quot;5.4 对抗训练同时包含两个优化问题&quot;">​</a></h3><p>判别器过强会让策略奖励稀疏，策略过强或数据覆盖不足又会让判别器失去区分能力。更新频率、正则和数据平衡都影响稳定性。</p><p><img src="'+n+'" alt="GAIL 的判别器与策略对抗更新"></p><h2 id="六、irl-与-gail-如何选择" tabindex="-1">六、IRL 与 GAIL 如何选择 <a class="header-anchor" href="#六、irl-与-gail-如何选择" aria-label="Permalink to &quot;六、IRL 与 GAIL 如何选择&quot;">​</a></h2><h3 id="_6-1-需要可解释奖励时选择-irl" tabindex="-1">6.1 需要可解释奖励时选择 IRL <a class="header-anchor" href="#_6-1-需要可解释奖励时选择-irl" aria-label="Permalink to &quot;6.1 需要可解释奖励时选择 IRL&quot;">​</a></h3><p>如果目标是分析舒适、效率和安全之间的权衡，显式奖励或代价模型更便于审计。</p><h3 id="_6-2-只关心行为分布时-gail-更直接" tabindex="-1">6.2 只关心行为分布时 GAIL 更直接 <a class="header-anchor" href="#_6-2-只关心行为分布时-gail-更直接" aria-label="Permalink to &quot;6.2 只关心行为分布时 GAIL 更直接&quot;">​</a></h3><p>GAIL 避免先恢复奖励再做 RL 的两阶段流程，但判别器奖励通常更难解释。</p><h3 id="_6-3-计算预算决定可用性" tabindex="-1">6.3 计算预算决定可用性 <a class="header-anchor" href="#_6-3-计算预算决定可用性" aria-label="Permalink to &quot;6.3 计算预算决定可用性&quot;">​</a></h3><p>IRL 可能嵌套多次 RL，GAIL 也需要持续采样和判别器训练。离线数据有限时要评估交互成本。</p><h3 id="_6-4-混合-bc-与-irl-gail-常更实用" tabindex="-1">6.4 混合 BC 与 IRL/GAIL 常更实用 <a class="header-anchor" href="#_6-4-混合-bc-与-irl-gail-常更实用" aria-label="Permalink to &quot;6.4 混合 BC 与 IRL/GAIL 常更实用&quot;">​</a></h3><p>BC 提供稳定初始化，IRL 或 GAIL 再优化长期分布，能降低从随机策略开始的对抗不稳定。</p><h2 id="七、自动驾驶中的示范偏差" tabindex="-1">七、自动驾驶中的示范偏差 <a class="header-anchor" href="#七、自动驾驶中的示范偏差" aria-label="Permalink to &quot;七、自动驾驶中的示范偏差&quot;">​</a></h2><h3 id="_7-1-司机风格不是安全规范" tabindex="-1">7.1 司机风格不是安全规范 <a class="header-anchor" href="#_7-1-司机风格不是安全规范" aria-label="Permalink to &quot;7.1 司机风格不是安全规范&quot;">​</a></h3><p>激进跟车、压线和不完整让行可能在数据中频繁出现，但不能因为专家做过就把它们当成可部署策略。</p><h3 id="_7-2-轨迹缺少反事实信息" tabindex="-1">7.2 轨迹缺少反事实信息 <a class="header-anchor" href="#_7-2-轨迹缺少反事实信息" aria-label="Permalink to &quot;7.2 轨迹缺少反事实信息&quot;">​</a></h3><p>示范只展示专家选择的动作，不告诉我们如果刹车、等待或换道会发生什么。IRL 无法凭空恢复所有反事实价值。</p><h3 id="_7-3-传感器和地图偏差会进入奖励" tabindex="-1">7.3 传感器和地图偏差会进入奖励 <a class="header-anchor" href="#_7-3-传感器和地图偏差会进入奖励" aria-label="Permalink to &quot;7.3 传感器和地图偏差会进入奖励&quot;">​</a></h3><p>专家看到的观测与部署感知不同，学到的奖励可能依赖不可用特征或数据采集条件。</p><p><img src="'+s+'" alt="自动驾驶示范、奖励学习与安全约束的边界"></p><h2 id="八、一个最小实验怎样设计" tabindex="-1">八、一个最小实验怎样设计 <a class="header-anchor" href="#八、一个最小实验怎样设计" aria-label="Permalink to &quot;八、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_8-1-用同一专家数据比较-bc、irl-和-gail" tabindex="-1">8.1 用同一专家数据比较 BC、IRL 和 GAIL <a class="header-anchor" href="#_8-1-用同一专家数据比较-bc、irl-和-gail" aria-label="Permalink to &quot;8.1 用同一专家数据比较 BC、IRL 和 GAIL&quot;">​</a></h3><p>统一轨迹数量、环境步和评价场景，比较动作误差、状态分布距离、任务成功和安全指标。</p><h3 id="_8-2-检查专家轨迹质量" tabindex="-1">8.2 检查专家轨迹质量 <a class="header-anchor" href="#_8-2-检查专家轨迹质量" aria-label="Permalink to &quot;8.2 检查专家轨迹质量&quot;">​</a></h3><p>过滤碰撞、异常传感器和不完整轨迹，并单独保留长尾示范做泛化测试。</p><h3 id="_8-3-测量奖励解释稳定性" tabindex="-1">8.3 测量奖励解释稳定性 <a class="header-anchor" href="#_8-3-测量奖励解释稳定性" aria-label="Permalink to &quot;8.3 测量奖励解释稳定性&quot;">​</a></h3><p>改变特征、正则和随机种子，比较学到的奖励排序与策略性能是否一致。</p><h3 id="_8-4-做专家风格迁移实验" tabindex="-1">8.4 做专家风格迁移实验 <a class="header-anchor" href="#_8-4-做专家风格迁移实验" aria-label="Permalink to &quot;8.4 做专家风格迁移实验&quot;">​</a></h3><p>在不同驾驶员、路线和交通密度下测试，区分学习到的是任务目标还是数据采集习惯。</p><h2 id="九、最常见的实现错误" tabindex="-1">九、最常见的实现错误 <a class="header-anchor" href="#九、最常见的实现错误" aria-label="Permalink to &quot;九、最常见的实现错误&quot;">​</a></h2><h3 id="_9-1-把-irl-奖励当成唯一真相" tabindex="-1">9.1 把 IRL 奖励当成唯一真相 <a class="header-anchor" href="#_9-1-把-irl-奖励当成唯一真相" aria-label="Permalink to &quot;9.1 把 IRL 奖励当成唯一真相&quot;">​</a></h3><p>奖励是给定假设下的解释，必须报告非唯一性和特征限制。</p><h3 id="_9-2-判别器训练集泄漏" tabindex="-1">9.2 判别器训练集泄漏 <a class="header-anchor" href="#_9-2-判别器训练集泄漏" aria-label="Permalink to &quot;9.2 判别器训练集泄漏&quot;">​</a></h3><p>专家和策略数据切分、时间相关性和重复轨迹会影响判别器难度。</p><h3 id="_9-3-用判别器分数直接做安全指标" tabindex="-1">9.3 用判别器分数直接做安全指标 <a class="header-anchor" href="#_9-3-用判别器分数直接做安全指标" aria-label="Permalink to &quot;9.3 用判别器分数直接做安全指标&quot;">​</a></h3><p>“像专家”只是一种行为相似度，不能替代碰撞、越界和约束指标。</p><h3 id="_9-4-忽略对抗训练的奖励漂移" tabindex="-1">9.4 忽略对抗训练的奖励漂移 <a class="header-anchor" href="#_9-4-忽略对抗训练的奖励漂移" aria-label="Permalink to &quot;9.4 忽略对抗训练的奖励漂移&quot;">​</a></h3><p>判别器更新会改变策略奖励，价值网络面对非平稳目标，需单独监控。</p><h2 id="十、学到什么程度才算掌握" tabindex="-1">十、学到什么程度才算掌握 <a class="header-anchor" href="#十、学到什么程度才算掌握" aria-label="Permalink to &quot;十、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_10-1-能区分-bc、irl-与-gail" tabindex="-1">10.1 能区分 BC、IRL 与 GAIL <a class="header-anchor" href="#_10-1-能区分-bc、irl-与-gail" aria-label="Permalink to &quot;10.1 能区分 BC、IRL 与 GAIL&quot;">​</a></h3><p>你应能说明 BC 复制动作、IRL 解释奖励、GAIL 匹配占用分布。</p><h3 id="_10-2-能解释奖励不可辨识性" tabindex="-1">10.2 能解释奖励不可辨识性 <a class="header-anchor" href="#_10-2-能解释奖励不可辨识性" aria-label="Permalink to &quot;10.2 能解释奖励不可辨识性&quot;">​</a></h3><p>你应能指出示范不足、特征限制和策略不变变换如何导致多个奖励解。</p><h3 id="_10-3-能设计安全的示范评价" tabindex="-1">10.3 能设计安全的示范评价 <a class="header-anchor" href="#_10-3-能设计安全的示范评价" aria-label="Permalink to &quot;10.3 能设计安全的示范评价&quot;">​</a></h3><p>你应能把相似度、任务完成、安全约束和专家质量分开评价。</p><h3 id="_10-4-能进入-alphastar" tabindex="-1">10.4 能进入 AlphaStar <a class="header-anchor" href="#_10-4-能进入-alphastar" aria-label="Permalink to &quot;10.4 能进入 AlphaStar&quot;">​</a></h3><p>下一篇将把模仿学习、强化学习和多智能体训练放进一个复杂系统案例。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://ai.stanford.edu/~ang/papers/icml00-irl.pdf" target="_blank" rel="noreferrer">Ng 与 Russell《Algorithms for Inverse Reinforcement Learning》</a></p><p><a href="https://ai.stanford.edu/~ang/papers/icml04-apprentice.pdf" target="_blank" rel="noreferrer">Abbeel 与 Ng《Apprenticeship Learning via Inverse Reinforcement Learning》</a></p><p><a href="https://arxiv.org/abs/1606.03476" target="_blank" rel="noreferrer">Ho 与 Ermon《Generative Adversarial Imitation Learning》</a></p><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter11/chapter11.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十一章模仿学习</a></p>',101)])])}const L=e(d,[["render",c]]);export{g as __pageData,L as default};
